  "invite_link_config": "{\"variant\": 1002, \"body\": {\"en\": \"Wanna do this?\", \"pt\": \"Quero adicionar voc\u00ea \u00e0 minha tela de in\u00edcio com o Locket. Toque no link para aceitar \ud83d\udc9b\", \"fr\": \"Je veux t'ajouter \u00e0 mon \u00e9cran d\u2019accueil avec Locket. Appuie sur le lien pour accepter \ud83d\udc9b\", \"es\": \"Quiero a\u00f1adirte a mi pantalla de inicio con Locket. Pulsa en el enlace para aceptar la invitaci\u00f3n \ud83d\udc9b\", \"ru\": \"\u042f \u0445\u043e\u0447\u0443 \u0434\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0432\u0430\u0441 \u0441\u0435\u0431\u0435 \u043d\u0430 \u044d\u043a\u0440\u0430\u043d \u0432 \u0432\u0438\u0434\u0436\u0435\u0442 Locket. \u0427\u0442\u043e\u0431\u044b \u043f\u0440\u0438\u043d\u044f\u0442\u044c \u043f\u0440\u0438\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435, \u043d\u0430\u0436\u043c\u0438\u0442\u0435 \u0441\u0441\u044b\u043b\u043a\u0443 \ud83d\udc9b\", \"th\": \"\u0e09\u0e31\u0e19\u0e15\u0e49\u0e2d\u0e07\u0e01\u0e32\u0e23\u0e40\u0e1e\u0e34\u0e48\u0e21\u0e04\u0e38\u0e13\u0e25\u0e07\u0e43\u0e19\u0e2b\u0e19\u0e49\u0e32\u0e2b\u0e25\u0e31\u0e01\u0e14\u0e49\u0e27\u0e22 Locket \u0e41\u0e15\u0e30\u0e25\u0e34\u0e07\u0e01\u0e4c\u0e40\u0e1e\u0e37\u0e48\u0e2d\u0e22\u0e2d\u0e21\u0e23\u0e31\u0e1a \ud83d\udc9b\", \"ar\": \"\ud83d\udc9b \u0623\u0631\u064a\u062f \u0625\u0636\u0627\u0641\u062a\u0643 \u0625\u0644\u0649 \u0634\u0627\u0634\u062a\u064a \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 Locket. \u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0631\u0627\u0628\u0637 \u0644\u0642\u0628\u0648\u0644 \u0627\u0644\u062f\u0639\u0648\u0629.\", \"id\": \"Saya ingin menambahkan Anda ke Layar Beranda saya dengan Locket. Ketuk tautan untuk menerima \ud83d\udc9b\", \"vi\": \"T\u00f4i mu\u1ed1n th\u00eam b\u1ea1n v\u00e0o m\u00e0n h\u00ecnh ch\u00ednh c\u1ee7a t\u00f4i qua Locket. Ch\u1ea1m v\u00e0o li\u00ean k\u1ebft \u0111\u1ec3 ch\u1ea5p nh\u1eadn \ud83d\udc9b\", \"ja\": \"Locket \u3067\u3042\u306a\u306e\u3092\u30db\u30fc\u30e0\u753b\u9762\u306b\u8ffd \u52a0\u3057\u305f\u3044\u3067\u3002\u30ea\u30f3\u30af\u3092\u30bf\u30c3\u30d7\u3057\u3066\u627f\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002\"}, \"title\": {\"en\": \"Add me on Locket \ud83d\udc9b\", \"pt\": \"Adicione-me no Locket \ud83d\udc9b\", \"fr\": \"Ajoute-moi sur Locket \ud83d\udc9b\", \"es\": \"A\u00f1\u00e1deme en Locket \ud83d\udc9b\", \"ru\": \"\u0414\u043e\u0431\u0430\u0432\u044c\u0442\u0435 \u043c\u0435\u043d\u044f \u0432 Locket \ud83d\udc9b\", \"th\": \"\u0e40\u0e1e\u0e34\u0e48\u0e21\u0e09\u0e31\u0e19\u0e25\u0e07\u0e43\u0e19 Locket \ud83d\udc9b\", \"ar\": \"\u0623\u0636\u0641\u0646\u064a \u0639\u0644\u0649 Locket \ud83d\udc9b\", \"id\": \"Tambahkan saya di Locket \ud83d\udc9b\", \"vi\": \"Th\u00eam t\u00f4i tr\u00ean Locket \ud83d\udc9b\", \"ja\": \"Locket \u3067\u79c1\u3092\u30a2\u30c3\u30c9\u3057\u3066\u304f\u3060\u3055\u3044 \ud83d\udc9b\"}, \"description\": {\"en\": \"I want to add you to my Home Screen with Locket. Tap the link to accept.\", \"pt\": \"Quero adicionar voc\u00ea \u00e0 minha tela de in\u00edcio com o Locket. Toque no link para aceitar.\", \"fr\": \"Je veux t'ajouter \u00e0 mon \u00e9cran d\u2019accueil avec Locket. Appuie sur le lien pour accepter.\", \"es\": \"Quiero a\u00f1adirte a mi pantalla de inicio con Locket. Pulsa en el enlace para aceptar la invitaci\u00f3n.\", \"ru\": \"\u042f \u0445\u043e\u0447\u0443 \u0434\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0432\u0430\u0441 \u0441\u0435\u0431\u0435 \u043d\u0430 \u044d\u043a\u0440\u0430\u043d \u0432 \u0432\u0438\u0434\u0436\u0435\u0442 Locket. \u0427\u0442\u043e\u0431\u044b \u043f\u0440\u0438\u043d\u044f\u0442\u044c \u043f\u0440\u0438\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435, \u043d\u0430\u0436\u043c\u0438\u0442\u0435 \u0441\u0441\u044b\u043b\u043a\u0443.\", \"th\": \"\u0e09\u0e31\u0e19\u0e15\u0e49\u0e2d\u0e07\u0e01\u0e32\u0e23\u0e40\u0e1e\u0e34\u0e48\u0e21\u0e04\u0e38\u0e13\u0e25\u0e07\u0e43\u0e19\u0e2b\u0e19\u0e49\u0e32\u0e2b\u0e25\u0e31\u0e01\u0e14\u0e49\u0e27\u0e22 Locket \u0e41\u0e15\u0e30\u0e25\u0e34\u0e07\u0e01\u0e4c\u0e40\u0e1e\u0e37\u0e48\u0e2d\u0e22\u0e2d\u0e21\u0e23\u0e31\u0e1a.\", \"ar\": \"\u0623\u0631\u064a\u062f \u0625\u0636\u0627\u0641\u062a\u0643 \u0625\u0644\u0649 \u0634\u0627\u0634\u062a\u064a \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 Locket. \u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0631\u0627\u0628\u0637 \u0644\u0642\u0628\u0648\u0644 \u0627\u0644\u062f\u0639\u0648\u0629.\", \"id\": \"Saya ingin menambahkan Anda ke Layar Beranda saya dengan Locket. Ketuk tautan untuk menerima.\", \"vi\": \"T\u00f4i mu\u1ed1n th\u00eam b\u1ea1n v\u00e0o M\u00e0n h\u00ecnh ch\u00ednh c\u1ee7a t\u00f4i qua Locket. Ch\u1ea1m v\u00e0o li\u00ean k\u1ebft \u0111\u1ec3 ch\u1ea5p nh\u1eadn.\", \"ja\": \"Locket \u3067\u3042\u306a\u306e\u3092\u30db\u30fc\u30e0\u753b\u9762\u306b\u8ffd \u52a0\u3057\u305f\u3044\u3067\u3002\u30ea\u30f3\u30af\u3092\u30bf\u30c3\u30d7\u3057\u3066\u627f\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002\"}, \"image\": {\"en\": \"en\", \"pt\": \"pt\", \"fr\": \"fr\", \"es\": \"sp\"}, \"exclude_url_from_body\": false, \"link_preview_variant\": 2}",
